SELECT a.id, a.applicant_user_id, snapshot.applicant_username, a.image_id, snapshot.target_name AS filename, snapshot.target_url AS oss_url, a.apply_reason, a.status, a.reviewer_user_id, snapshot.reviewer_username, a.reject_reason, a.create_time, a.review_time, a.update_time FROM biz_image_audit_record a LEFT JOIN audit_query_record_projection snapshot ON snapshot.target_type = 'IMAGE' AND snapshot.audit_id = a.id
a.status = #{status} AND a.applicant_user_id = #{applicantUserId}
ORDER BY a.update_time DESC, a.id DESC
